const RERK_GOOD = { "อำมฤตโชค": 3, "มหาสิทธิโชค": 2, "สิทธิโชค": 1, "ราชาโชค": 1, "ชัยโชค": 1 };   // ค่า = จำนวนดาวในปฏิทินวัดท่าขนุน
const RERK_NOTE = { "พิฆาต": "ดิถีพิฆาต ตำราห้ามเด็ดขาด", "โลกาวินาศ": "ห้ามเริ่มการใหญ่", "มฤตยู": "ห้ามการมงคล" };
const DSTAT_CLS = { "ดี": "g", "ปกติ": "", "ดี/ร้าย": "m", "ร้าย": "b" };
const dithOff = L => (L.phase === "ขึ้น" ? L.kham - 1 : L.kham + 14);
// d = วันโหร · L = ผลจาก lunarTbl(d) → ฤกษ์ สถานะวัน ทิศพระกาฬจร ของวันนั้น
function extrasOf(d, L) {
  if (!d || !L) return null;
  const w = d.getDay(), off = dithOff(L);
  const names = RERK7x30[w][off].split(", ").filter(x => x !== "-");
  const good = names.filter(n => RERK_GOOD[n]), bad = names.filter(n => !RERK_GOOD[n]);
  return { off, w, names, good, bad, stars: good.reduce((m, n) => Math.max(m, RERK_GOOD[n]), 0),
           stat: DSTAT7x30[w][off], kala: KALA30[off], note: names.map(n => RERK_NOTE[n]).filter(Boolean) };
}
// v3.9.24 ⑥ ข้อ 31: สัญลักษณ์ฤกษ์ตามไฟล์ thai_lunar_calendar.csv ที่ผู้ใช้ส่ง (22 พ.ย. 2569)
const RERK_SYM = { "อำมฤตโชค": "⭐⭐⭐", "มหาสิทธิโชค": "⭐⭐", "สิทธิโชค": "⭐", "ราชาโชค": "👑", "ชัยโชค": "🏆" };
const rerkTxt = e => (e.names.length ? e.good.map(n => `${RERK_SYM[n] || ""} ${n}`.trim()).concat(e.bad).join(" · ") : "ไม่มีชื่อฤกษ์ในตาราง");

// ================= v3.9.24 ⑥ ข้อ 31: คอลัมน์เสริมจากไฟล์ปฏิทิน (คำนวณใหม่ตามดิถีของแอป) =================
// ดิถี เดือน วันพระ ใช้ของแอป (lunarTbl) เพราะไฟล์ต่างจาก myhora ๑ วันใน ๓๓ ปี (ตรวจ ๖/๖ ปี แอปถูก)
// จ.ศ.: วันเถลิงศกเดือนเมษายนรายปีจากไฟล์ ค.ศ. 1937–2057 (ตัวเลข + 13 = วันที่) · นอกช่วงไฟล์ประมาณ 15 เม.ย. (1936) และ 16 เม.ย. (2058)
const THLS = { y0: 1937, s: "2232233223322332233223322332233233323332333233323332333233333333333333333333333333333333334333433343334333433343334334433" };
const thlsDay = y => { const k = THLS.s[y - THLS.y0]; return k ? 13 + +k : (y < THLS.y0 ? 15 : 16); };
const csOf = d => { const y = d.getFullYear(), m = d.getMonth(); return y - 638 - (m < 3 || (m === 3 && d.getDate() < thlsDay(y)) ? 1 : 0); };
const lunType = be => LUN.types[be - LUN.be0] || "";
function wanTypeOf(L, next) {
  if (!L || !isWanPhra(L, next)) return "";
  if (L.kham === 8) return L.phase === "ขึ้น" ? "🌓 ขึ้น 8 ค่ำ (วันพระเล็ก)" : "🌗 แรม 8 ค่ำ (วันพระเล็ก)";
  return L.phase === "ขึ้น" ? "🌕 ขึ้น 15 ค่ำ (วันเพ็ญ วันพระใหญ่)" : `🌑 แรม ${L.kham} ค่ำ (วันดับ วันพระใหญ่)`;
}
// วันสำคัญทางพุทธศาสนา · ปีอธิกมาส (m) เลื่อนไป ๑ เดือน · มาฆะอยู่ปลายปีจันทรคติ จึงดูชนิดของปีถัดไป
function buddhaDayOf(L) {
  if (!L) return "";
  const am = lunType(L.be) === "m", amNext = lunType(L.be + 1) === "m", up = L.phase === "ขึ้น";
  const m8 = am ? (L.month === 8 && L.m8 === "หลัง") : (L.month === 8 && !L.m8);
  if (up && L.kham === 15 && L.month === (amNext ? 4 : 3)) return "วันมาฆบูชา";
  if (L.month === (am ? 7 : 6) && !L.m8) { if (up && L.kham === 15) return "วันวิสาขบูชา"; if (!up && L.kham === 8) return "วันอัฏฐมีบูชา"; }
  if (m8) { if (up && L.kham === 15) return "วันอาสาฬหบูชา"; if (!up && L.kham === 1) return "วันเข้าพรรษา"; }
  if (L.month === 11 && up && L.kham === 15) return "วันออกพรรษา";
  return "";
}
function dayNoteOf(d, L) {
  if (!d || !L || d.getDay() !== 6) return "";
  if (L.kham === 11) return "⚠️ ชัยโชควันเสาร์ 11 ค่ำ ตรงกับดิถีวันบอด ควรเลี่ยง";
  if (L.phase === "ขึ้น" && L.kham === 5) return "🙏 วันเสาร์ ขึ้น 5 ค่ำ หลวงพ่อฤๅษีลิงดำห้ามทำการมงคล";
  return "";
}
const PHIKAT_K = [12, 11, 7, 3, 6, 9, 8];   // ดิถีพิฆาต วันอาทิตย์–เสาร์ (ขึ้นหรือแรม)
// d = วันโหร · L = lunarTbl(d) → คอลัมน์เสริมของวันนั้น
function calExtraOf(d, L) {
  if (!d || !L) return null;
  const next = lunarTbl(addDays(d, 1));
  return { cs: csOf(d), wanType: wanTypeOf(L, next), holiday: buddhaDayOf(L), note: dayNoteOf(d, L),
           phikat: L.kham === PHIKAT_K[d.getDay()], yearType: { n: "ปกติมาส ปกติวาร (๓๕๔ วัน)", v: "อธิกวาร (๓๕๕ วัน)", m: "อธิกมาส (๓๘๔ วัน)" }[lunType(L.be)] || "" };
}
const thd = t => String(t).replace(/[0-9]/g, x => "๐๑๒๓๔๕๖๗๘๙"[x]);   // ข้อความในไฟล์ใช้เลขอารบิก แสดงเป็นเลขไทย
const calExtraTxt = c => !c ? "" : [c.holiday ? `<b>${esc(c.holiday)}</b>` : "", c.wanType ? esc(thd(c.wanType)) : "", c.phikat ? `<span class="b">ดิถีพิฆาต</span>` : "", c.note ? `<span class="b">${esc(thd(c.note))}</span>` : "", "จ.ศ. " + TH(c.cs)].filter(Boolean).join(" · ");

// ===== ยกจาก v7.6.6 บรรทัด 651–656: ปีนักษัตรจากปีจันทรคติ =====
function naksatFor(astroDate, lunarMonth, be) {
  if (be >= 2400) return ((be - 547) % 12 + 12) % 12 + 1;   // v7.3 ปีจันทรคติจากตาราง (เปลี่ยนวันขึ้น ๑ ค่ำ เดือน ๕)
  let y = astroDate.getFullYear();
  if (lunarMonth >= 1 && lunarMonth <= 4 && astroDate.getMonth() + 1 <= 5) y -= 1;   // ปีเปลี่ยนวันขึ้น ๑ ค่ำ เดือน ๕
  return ((y - 4) % 12 + 12) % 12 + 1;
}

