const fm = NODE ? null : FileManager.local();
const DIR = NODE ? "" : fm.joinPath(fm.documentsDirectory(), "satta7");
// v1.0.0 เปลี่ยนชื่อโฟลเดอร์จาก yam7_natal → satta7 · ถ้าของเดิมมีอยู่ให้ย้ายดวงที่บันทึกไว้มาให้ครบ
if (!NODE) {
  const OLD = fm.joinPath(fm.documentsDirectory(), "yam7_natal");
  if (!fm.fileExists(DIR)) {
    fm.createDirectory(DIR, true);
    if (fm.fileExists(OLD)) ["profiles.json", "state.json"].forEach(f => {
      const a = fm.joinPath(OLD, f); if (fm.fileExists(a)) { try { fm.copy(a, fm.joinPath(DIR, f)); } catch (e) {} } });
  }
}
const F_PROFILES = NODE ? "" : fm.joinPath(DIR, "profiles.json");
const F_STATE    = NODE ? "" : fm.joinPath(DIR, "state.json");
const readJSON = f => { try { return (!NODE && fm.fileExists(f)) ? JSON.parse(fm.readString(f)) : null; } catch (e) { return null; } };
const writeJSON = (f, o) => { if (!NODE) fm.writeString(f, JSON.stringify(o)); };

// ================= ปี พ.ศ. และเดือนสุริยคติ =================
const TH_MON   = ["มกราคม","กุมภาพันธ์","มีนาคม","เมษายน","พฤษภาคม","มิถุนายน","กรกฎาคม","สิงหาคม","กันยายน","ตุลาคม","พฤศจิกายน","ธันวาคม"];
const TH_MON_S = ["ม.ค.","ก.พ.","มี.ค.","เม.ย.","พ.ค.","มิ.ย.","ก.ค.","ส.ค.","ก.ย.","ต.ค.","พ.ย.","ธ.ค."];
// ก่อนปี พ.ศ. ๒๔๘๔ ปีใหม่ไทยคือ ๑ เมษายน → วันที่ ๑ ม.ค.–๓๑ มี.ค. ยังเป็น พ.ศ. ปีก่อน (ค.ศ. + ๕๔๒)
const oldBE = d => { const y = d.getFullYear(), m = d.getMonth() + 1; return (y < 1941 && m <= 3) ? y + 542 : y + 543; };
const beOfAD = d => d.getFullYear() + 543;              // ปี พ.ศ. แบบปัจจุบัน (ปีใหม่ ๑ ม.ค.)
const isOldBE = d => d.getFullYear() < 1941 && d.getMonth() + 1 <= 3;   // ช่วงที่ พ.ศ. เก่า/ใหม่ ไม่เท่ากัน
const beText = d => (isOldBE(d) ? `${TH(oldBE(d))} (ปีใหม่ ๑ เม.ย. · นับแบบปัจจุบัน ${TH(beOfAD(d))})` : TH(beOfAD(d)));
const dateTH  = d => `${TH(d.getDate())} ${TH_MON[d.getMonth()]} ${beText(d)}`;
const dateTHs = d => `${TH(d.getDate())} ${TH_MON_S[d.getMonth()]} ${TH(oldBE(d))}`;

// ================= ผังเกิด ๙ ฐาน =================
// p = { name, iso ("YYYY-MM-DD"), time ("HH:MM" หรือ null), sex, order, lunar (กรอกเองถ้านอกช่วงตาราง) }
const dateOfProfile = p => {
  const [y, m, d] = String(p.iso).split("-").map(Number);
  const [hh, mm] = p.time ? String(p.time).split(":").map(Number) : [12, 0];
  return new Date(y, m - 1, d, hh || 0, mm || 0, 0, 0);
};
function natalChart(p) {
  const born = dateOfProfile(p);
  const hasTime = !!p.time;
  // วันโหร: เกิดก่อน ๐๖:๐๐ นับเป็นวันก่อนหน้า (ถ้าไม่รู้เวลาเกิด ให้ใช้วันตามปฏิทินโดยไม่เลื่อน)
  const astro = hasTime ? astroDateOf(born) : dateOnly(born);
  const dayIdx = astro.getDay(), dayNum = dayIdx + 1;
  const h = hasTime ? yamClock(born).getHours() : 12;
  const isNight = hasTime ? (h < CFG.dayStartHour || h >= CFG.dayStartHour + 12) : false;
  const taksaLord = (dayIdx === 3 && isNight) ? 8 : dayNum;   // พุธกลางคืน = ราหู (๘) ตำรา ภาค ๒ หน้า ๓๑๐
  const LTi = lunarTblInfo(astro);
  const lunar = LTi ? LTi.T : (p.lunar || null);
  const inTbl = !!LTi;
  if (!lunar) return { err: "วันเกิดอยู่นอกช่วงปฏิทินในตัว และยังไม่ได้กรอกเดือนจันทรคติเอง", astro, dayIdx, dayNum };
  const wanPhra = LTi ? LTi.wan : false;
  const monthForRow = lunar.m8 === "หลัง" ? CFG.month88 : lunar.month;
  const naksat = (!inTbl && p.naksat) ? p.naksat : naksatFor(astro, lunar.month, lunar.be);
  const rows = {
    day:   [...Array(7)].map((_, i) => step(dayNum, i)),
    month: [...Array(7)].map((_, i) => step(mod7(monthForRow), i)),
    year:  [...Array(7)].map((_, i) => step(mod7(naksat), i))
  };
  rows.sum = rows.day.map((v, i) => v + rows.month[i] + rows.year[i]);
  Object.defineProperty(rows, "sex", { value: (p && p.sex) || "", enumerable: false });   // v3.9.20 K6-03
  const B = base59(rows);
  return { p, born, hasTime, astro, dayIdx, dayNum, isNight, taksaLord, lunar, inTbl, wanPhra,
           monthForRow, naksat, rows, B, taksa: taksaOf(taksaLord), extras: inTbl ? extrasOf(astro, lunar) : null };
}
// ผังสังเคราะห์ (ใช้ในชุดทดสอบ ๑,๐๐๘ แบบ): ไม่มีวันเกิดจริง จึงไม่มีฤกษ์ ทิศ หรือวันพระ
function chartOf(dayNum, monthForRow, naksat, extra) {
  const rows = {
    day:   [...Array(7)].map((_, i) => step(dayNum, i)),
    month: [...Array(7)].map((_, i) => step(mod7(monthForRow), i)),
    year:  [...Array(7)].map((_, i) => step(mod7(naksat), i))
  };
  rows.sum = rows.day.map((v, i) => v + rows.month[i] + rows.year[i]);
  Object.defineProperty(rows, "sex", { value: (extra && extra.sex) || "", enumerable: false });
  return { p: { name: "ผังสังเคราะห์", ...(extra || {}) }, synth: true, dayIdx: dayNum - 1, dayNum, hasTime: false,
           lunar: { month: monthForRow, phase: "ขึ้น", kham: 1 }, monthForRow, naksat, inTbl: false,
           rows, B: base59(rows), taksa: taksaOf(dayNum), extras: null };
}
// ฐานรองรับของดวงกำเนิด = ฐานรวมของหลักที่เลขนั้นอยู่ใน "แถวปี" (ตำรา ภาค ๒ หน้า ๑๘๒–๑๘๓ · KB หัวข้อ ๑๙)
// ต่างจากแอปจับยามที่ลากดิ่งจากหลักที่ดาวจรตก — อย่าสลับกัน
function supNatal(n, rows) {
  const col = rows.year.indexOf(n);
  if (col < 0) return null;
  const sum = rows.sum[col];
  return { col, sum, grp: SUMGRP(sum), name: sumName(sum), house: HSX(rows).year[col] };
}
// ชื่อเรือนตามหลัก
const houseAt = (k, col, o) => (k === "b8" ? H8[col] : k === "b9" ? H9[col] : HSX(o)[k][col]);

// ทักษาพื้นชะตา ๘ ภูมิจากวันเกิด (ยกจาก v7.6.6) — ใช้ทำเครื่องหมาย ⭐ ศรี และ 🔥 กาลกิณี บนผัง
function taksaOf(lord) {
  const s = TAKSA_ORDER.indexOf(lord), map = {};
  TAKSA_ORDER.forEach((p, i) => { map[p] = TAKSA_ROLE[(i - s + 8) % 8]; });
  return map;
}
const TK_ICON = { ศรี: "⭐", กาลกิณี: "🔥" };

// ================= โปรไฟล์วันเกิด =================
const profiles = () => readJSON(F_PROFILES) || [];
const stateGet = () => readJSON(F_STATE) || {};
const curProfile = () => { const L = profiles(), st = stateGet(); return L.find(x => x.id === st.curId) || L[0] || null; };
const saveProfile = p => {
  const L = profiles(), i = L.findIndex(x => x.id === p.id);
  if (i >= 0) L[i] = p; else L.unshift(p);
  writeJSON(F_PROFILES, L.slice(0, CFG.profileMax));
  writeJSON(F_STATE, { ...stateGet(), curId: p.id });
  return p;
};
const newId = () => `p${Date.now().toString(36)}`;
const SEX_TH = { m: "ชาย", f: "หญิง", "": "ไม่ระบุ" };
// ตรวจค่าที่กรอก: วันที่ต้องมีจริง · อยู่ในช่วงปฏิทินในตัว · เวลาถูกรูปแบบ
function validProfile(o) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(o.iso || ""));
  if (!m) return "รูปแบบวันเกิดไม่ถูกต้อง";
  const y = +m[1], mo = +m[2], d = +m[3], dt = new Date(y, mo - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== mo - 1 || dt.getDate() !== d) return `ไม่มีวันที่ ${TH(d)} ${TH_MON[mo - 1] || mo} ${TH(y + 543)} จริง`;
  if (o.time && !/^\d{1,2}:\d{2}$/.test(String(o.time))) return "รูปแบบเวลาเกิดไม่ถูกต้อง (ใช้ HH:MM)";
  if (!lunarTbl(dt)) return `วันเกิดอยู่นอกช่วงปฏิทินในตัว (${LUN_RANGE})`;
  return null;
}

// ================= หน้าแอป =================
const esc = s => String(s === null || s === undefined ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
