function tbFlat(html) {
  const at = (a, k) => (((a || "").match(new RegExp(`${k}="([^"]*)"`)) || [])[1] || "");
  return String(html).replace(/<div class="tbw">\s*<table class="tb"[^>]*>([\s\S]*?)<\/table>\s*<\/div>/g, (all, inner) => {
    const rows = [...inner.matchAll(/<tr([^>]*)>([\s\S]*?)<\/tr>/g)].map(m => ({ a: m[1],
      c: [...m[2].matchAll(/<(t[hd])([^>]*)>([\s\S]*?)<\/t[hd]>/g)].map(x => ({ t: x[1], a: x[2], h: x[3] })) })).filter(r => r.c.length);
    if (!rows.length) return all;
    const head = rows[0].c.every(x => x.t === "th") ? rows.shift().c.map(x => x.h) : null;
    if (head && head.length > 5 && rows.length <= 4) {
      const n = head.length - 1;
      return `<div class="tiles${n === 7 ? " t7" : ""}">${head.slice(1).map((hh, j) => `<div class="tl"><span class="th">${head[0]} ${hh}</span>${rows.map(r => { const c = r.c[j + 1]; return c ? `<span class="tv ${at(c.a, "class")}">${c.h}</span>` : ""; }).join("")}</div>`).join("")}</div>`;
    }
    return `<div class="stk">${rows.map(r => { const [f, ...rest] = r.c, st = at(r.a, "style");
      return `<div class="sr"${st ? ` style="${st}"` : ""}><div class="s1 ${at(f.a, "class")}">${f.h}</div>${rest.map((c, j) => `<div class="sd ${at(c.a, "class")}">${head && head[j + 1] ? `<span class="sl">${head[j + 1]}:</span>` : ""}${c.h}</div>`).join("")}</div>`; }).join("")}</div>`;
  });
}
