  // เด่น ๓ / ระวัง ๓ จากเรือนของฐาน ๑–๓ (๒๑ ภพ ที่มีความหมายรายเรื่อง)
  const r3 = out.day.concat(out.month, out.year);
  const tone = x => houseTone(x.h, x.key);
  // เลขหนึ่งตัวตั้งหลายเรือน ตำราอ่านรวมกัน (เช่น "๑ ตนุ–โภคา–ลาภะ") จึงเก็บเรือนเด่นหนึ่งเรือนต่อเลข แล้วพ่วงเรือนที่เหลือไว้ใน also
  const dedup = (list, n) => { const seen = {}, out2 = [];
    list.forEach(x => { if (seen[x.n] === undefined) { seen[x.n] = out2.length; out2.push({ ...x, also: [] }); }
                        else out2[seen[x.n]].also.push(x.h); });
    return out2.slice(0, n); };
  out.top = dedup(r3.filter(x => tone(x) >= 0 && x.sc.lv >= 1).sort((a, b) => b.sc.score - a.sc.score), 3);
  const risk = x => (tone(x) < 0 ? x.sc.score : 100 - x.sc.score);   // เรือนเสียคะแนนสูง = เรื่องร้ายหนักแน่น · เรือนดีคะแนนต่ำ = เรื่องดีไม่ได้ผล
  out.warn = dedup(r3.filter(x => (tone(x) < 0 && x.sc.score >= 70) || (tone(x) >= 0 && x.sc.lv <= -1))
               .sort((a, b) => risk(b) - risk(a)), 3);
  out.warnWhy = x => (houseTone(x.h, x.key) < 0 ? "เรือนเสียแต่เลขและฐานหนักแน่น เรื่องร้ายนี้เด่นชัด" : "เลขและฐานรองรับอ่อน เรื่องนี้ไม่ได้ผลเท่าที่ควร");
