function trNow(ch, nowIn) {
  if (ch.synth || !ch.lunar || !ch.inTbl) return null;
  const now = nowIn || appNow();
  if (ageYang(ch.born, now) < 1) return null;
  const astroNow = astroDateOf(now), Ln = lunarTbl(astroNow), age = ageYang(ch.born, now);
  const Y = trYear(ch, age), M = Ln ? trMonth(ch, Ln.month) : null, D = trDay(ch, astroNow.getDay());
  const yr = yamRead({ hasTime: true, born: now, dayIdx: astroNow.getDay() });
  const Ym = yr ? trYam(ch, astroNow.getDay(), yr.no) : null;
  return { now, astroNow, Ln, age, Y, M, D, Ym };
}
