function relLines(rel) {
  const G = [];
  rel.forEach(r => { const nm = `${r.h}${r.k && is89(r.k) ? `(${B89TH[r.k]})` : ""}`, g = G.find(x => x.t === r.t);
    if (g) { if (!g.h.includes(nm)) g.h.push(nm); } else G.push({ t: r.t, h: [nm] }); });
  return G.map(g => `${esc(g.h.join(" · "))}: ${esc(g.t)}`).join("<br>");
}
function houseBlock(x, first, tag) {
  const rel = x.rel.length ? `<div class="hl">${relLines(x.rel)}</div>` : "";
  return `<div class="hr${first ? " first" : ""}"><div class="hn2"><span class="nm">${esc(x.h)}${tag ? ` <small>${esc(tag)}</small>` : ""} ${TH(x.n)} ${esc(P[x.n].n)}</span>${scPill(x.sc, x.h, x.key)}</div><div class="hn"><span class="w">${esc(x.mean || "")}</span></div>
<div class="hl">${x.lines.map(esc).join("<br>")}</div>${rel}</div>`;
}
// v3.9.18 เลขเดียวกัน → ฐานรองรับ คำดาวบนฐาน และคำฐานเป็นชุดเดียวกัน (ฐาน ๘ ๙ ใช้ฐานรองรับของเลขตัวเดียวกันในแถวปี)
function selfEcho(sf, x, tag) {
  const m = [[sf.atta, "อัตตะ แถววัน"], [sf.tanu, "ตนุ แถวเดือน"]].find(([y]) => y && y.n === x.n);
  if (!m) return houseBlock(x, false, tag);
  return `<div class="hr"><div class="hn2"><span class="nm">${esc(x.h)} <small>${esc(tag)}</small> ${TH(x.n)} ${esc(P[x.n].n)}</span>${scPill(x.sc, x.h, x.key)}</div><div class="hn"><span class="w">${esc(x.mean || "")}</span></div>
<div class="hl">เลข ${TH(x.n)} ตัวเดียวกับ${esc(m[1])} · ฐานรองรับ คำดาวบนฐาน และคำฐาน เหมือนด้านบน (ฐาน ๘ ๙ ใช้ฐานรองรับของเลขตัวเดียวกันในแถวปี)</div></div>`;
}
function selfCard(ch, rd) {
  const sf = rd.self, pk = pakRead(ch);
  const pkLine = p => `<div class="hr"><div class="hn2"><span class="nm">${esc(p.lab)} = ${esc(p.h)} ${TH(p.n)} ${esc(P[p.n].n)}</span>${scPill(p.sc, p.h, p.lab === "ที่นั่ง" ? "year" : p.lab === "ใจ" ? "month" : "day")}</div><div class="hn"><span class="w">${esc(p.what)}</span></div>
<div class="hl">${esc(p.t)}</div>${p.rel.length ? `<div class="hl">${relLines(p.rel)}</div>` : ""}</div>`;
  return `<div class="card"><h2>ตัวเจ้าชะตา <span>อัตตะ ตนุ อาตมา · ปาก ใจ ที่นั่ง</span></h2>
${houseBlock(sf.atta, true)}${houseBlock(sf.tanu)}
${selfSexH(ch)}
${selfEcho(sf, sf.atma, "ฐาน ๘")}${selfEcho(sf, sf.atta9, "ฐาน ๙")}
<details class="grp"><summary>ปาก ใจ ที่นั่ง <span class="sm2">${pk.map(p => `${esc(p.lab)} ${TH(p.n)}`).join(" · ")}</span></summary>${pk.map(pkLine).join("")}</details>
<details><summary>ที่มา</summary><div class="foot">
อัตตะ (เลขวันเกิด) และตนุ (เลขเดือนเกิด) คือตัวเจ้าชะตาทั้งคู่ · อาตมา (ฐาน ๘) และอัตตะ (ฐาน ๙) เป็นเรือนประกอบ (ภาค ๑ หน้า ๑๒ · ภาค ๒ หน้า ๑๘๒–๑๘๓)<br>
ปาก = เลขปิตา · ใจ = เลขพันธุ · ที่นั่ง = เลขลาภะ (ภาค ๑ หน้า ๑๐๕–๑๑๒ · ภาค ๒ หน้า ๑๘๕–๑๘๖) ศุภเคราะห์ ๒ ๔ ๕ ๖ พูดจานิ่มนวล ใจเย็น ได้มากอยู่นาน · บาปเคราะห์ ๑ ๓ ๗ พูดโผงผาง ใจร้อน ได้น้อยไม่นาน · ถ้าชนเสียจะเสียแบบของดาวตัวนั้น
</div></details></div>`;
}
function housesCard(ch, rd) {
  const grp = ([k, lab]) => `<details><summary>${esc(lab)} (๗ ภพ)</summary>${rd[k].map((x, i) => houseBlock(x, i === 0)).join("")}</details>`;
  return `<div class="card"><h2>คำอ่านรายเรือน ๓๕ ภพ <span>ฐานรองรับแบบแถวปี</span></h2>
${NAT_ROWS.map(grp).join("")}
<div class="foot" style="margin-top:9px">ลำดับการอ่านตามตำรา ภาค ๒ หน้า ๑๘๒–๑๙๖ · ฐาน ๘ ๙ ใช้ฐานรองรับของเลขตัวเดียวกันในแถวปีเช่นเดียวกัน</div></div>`;
}

