// "ชั่วบวกชั่วเป็นดี" นิยามตามตำรา = มรณะเป็นเลขตัวเดียวกับหินะ หรือเป็นเลขตัวเดียวกับอริ (คู่ใดคู่หนึ่งก็ได้)
// ภาค ๑ หน้า ๓๖๓ (วงเล็บว่า "มรณะต้องเป็นตัวยืน เพื่อสลายความชั่วอื่นให้หมดไป") · ภาค ๒ หน้า ๒๔๐ และ ๒๕๘ นิยามซ้ำคำเดียวกัน
// ผังตัวอย่างที่ตำราอ่านว่าเข้าเกณฑ์นี้ใช้นิยามนี้ทั้งหมด: อาจารย์จำรัส หน้า ๑๗๕ · อาจารย์เชย หน้า ๑๗๖ · ดวงนายตำรวจ หน้า ๑๙๐–๑๙๒ · หน้า ๒๗๓
// ก่อน v1.0.0 เคยนับคู่ภพเสียคู่ใดก็ได้ (รวมมหาอุบาทว์) จึงติดถึง ๘๒.๓% ของผัง — นิยามนี้เหลือ ๒๖.๒% และตรงกับเกณฑ์พื้นดวงใน tqNatal
function NAT_BB(ch) {
  const mn = numAtH(ch, "year", "มรณะ"), out = [];
  if (mn == null) return out;
  [["day", "หินะ"], ["month", "อริ"]].forEach(([k, h]) => { if (numAtH(ch, k, h) === mn) out.push(`มรณะ|${h}`); });
  return out;
}
// คำอ่านระดับเลข: เลขตัวเดียวไปตั้งในภพเสียหลายภพพร้อมกัน ตำราถือว่าความเสียลดทอนกันเอง
// (ภาค ๑ ดวงการศึกษา "อริ – มหาอุบาทว์ + มรณะ = ชั่ว + ชั่ว กลับกลายเป็นดี") — เป็นข้อสังเกตประกอบ ไม่ให้คะแนน และไม่ใช่เกณฑ์พื้นดวง
const NAT_BB_WIDE = c => !!c && !!c.heavy && c.heavy.length >= 2;

// ---------- เกณฑ์ดวงชะตาหมอดู ๖ ข้อ (ตำรา ภาค ๑ หน้า ๑๗๓–๑๗๔) ----------
