  return `<div class="kv ruk"${hlA("ru-" + r.id, hlRule(ch, r))}>${ruleIc(r)} <b>${esc(r.n)}</b> ${eff}${r.hard ? ' <span class="pill">คำแรงในตำรา</span>' : ""}<br>
<span class="hl">${esc(r.t)}${x.extra ? ` (${esc(x.extra)})` : ""}</span><br><span class="foot">${esc(r.src)}${r.freq ? ` · พบใน ${esc(r.freq)} ของแบบผังทั้งหมด` : ""}${r.note ? `<br>หมายเหตุ: ${esc(r.note)}` : ""}</span></div>`;
