function numHTML(ch, n) {
  if (!(n >= 1 && n <= 7)) return "";
  const L = linksOf(n, ch.rows, ch.B), sup = supNatal(n, ch.rows), tt = natTopics(ch);
  const sc = houseScore(n, L[0].k, ch);
  const rel = [];
  L.forEach((a, i) => L.slice(i + 1).forEach(b => { const t = relText(a.h, b.h); if (t) { const ln = `${a.h}–${b.h}: ${t}`; if (!rel.includes(ln)) rel.push(ln); } }));   // รอบ 82: ตัดบรรทัดซ้ำ
  const tps = tt.list.filter(s => (s.cells || []).some(c => c.n === n || (c.items || []).length && c.n === n));
  // v3.7.0 ข๕ เลขชิ่งของเลขนี้ในทุกที่ที่อยู่ในแถว ๑–๓ (ฐาน ๑↔๕ ๒↔๖ ๓↔๗ หลักเดียวกัน) · ตรงกับเลขชิ่งในผัง
  const chingH = (() => { const items = L.filter(x => CHING_PAIR[x.k]).map(x => { const m = ch.B[CHING_PAIR[x.k]][x.c];
      const t = m === n ? "เลขคู่เป็นตัวเดียวกัน ชิ่งกลับตัวเอง ย้ำเรือนเดิม"
        : `เลขคู่ ${TH(m)} ${esc(P[m].n)} พ่วงเรื่อง · อยู่ที่ ${linksOf(m, ch.rows, ch.B).map(y => esc(y.h)).join(" · ")}`;
      return `<div class="kv">• <b>${esc(x.h)}</b> ${t}</div>`; });
    return items.length ? `<div class="card"><h2>เลขชิ่งของเลข ${TH(n)}</h2>${items.join("")}<div class="foot" style="margin-top:7px">${esc(CHING_NOTE)}</div></div>` : ""; })();
  const block = x => { const s2 = houseScore(n, x.k, ch), inv = houseTone(x.h, x.k) < 0;
    return `<div class="kv">• <b>${esc(x.h)}</b>${is89(x.k) ? ` (${B89TH[x.k]})` : ` (${{ day: "ฐาน ๑", month: "ฐาน ๒", year: "ฐาน ๓" }[x.k]})`} ${scPill(s2, x.h, x.k)}<br>
<span class="hl">${esc(meanOf(x.h, x.k) || "")}</span></div>`; };
  return page(`เลข ${TH(n)}`, `<div class="top"><h1>เลข ${TH(n)} ${esc(P[n].n)}</h1>
<div class="ts">${esc(isSup(n) ? "ศุภเคราะห์ — ได้มากและอยู่นาน" : "บาปเคราะห์ — ได้น้อยและอยู่ไม่นาน")} · ${esc(ch.p.name || "ดวงนี้")}</div></div>
<div class="card"><h2>เลขนี้ตั้งอยู่ ${TH(L.length)} ที่</h2>${L.map(block).join("")}
<div class="kv">ฐานรองรับ: ${sup ? `${TH(sup.sum)} ${esc(sumName(sup.sum))} (${esc(GRP_TH[["bad", "mid", "good"].indexOf(sc.grp)])})` : "ไม่พบเลขนี้ในแถวปี จึงไม่มีฐานรองรับ"}</div>
<div class="kv">${esc(chonTxt(sc.cn))}</div>
${NAT_BB_WIDE(sc.cn) ? `<div class="kv" style="color:var(--tx3);font-size:11.5px">ข้อสังเกต: เลขนี้ไปตั้งในภพเสียหลายภพพร้อมกัน (${esc(sc.cn.heavy.join(" "))}) ตำราภาค ๑ มีคำอ่านว่าความเสียลดทอนกันเอง "ชั่ว + ชั่ว กลับกลายเป็นดี" — เป็นข้อสังเกตประกอบ ไม่ได้คิดคะแนน และไม่ใช่เกณฑ์ชั่วบวกชั่วของพื้นดวงซึ่งต้องเป็นมรณะกับหินะหรืออริ</div>` : ""}
<details><summary>คะแนนของเลขนี้คิดมาอย่างไร</summary><div class="foot">${sc.parts.map(p => `${p.d ? sgn(p.d) + " · " : ""}${esc(p.why)}`).join("<br>")}</div></details></div>
${chingH}
${rel.length ? `<div class="card"><h2>เรือนที่เลขนี้โยงถึงกัน</h2><div class="hl">${rel.map(esc).join("<br>")}</div>
<div class="foot" style="margin-top:7px">เรือนสัมพันธ์ ๑๔๖ คู่ ตำรา ภาค ๑ หน้า ๑๔–๒๕</div></div>` : ""}
${PSTRONG[n] ? `<div class="card"><h2>ลักษณะของ${esc(P[n].n)}</h2>${starNumH(ch, n)}<div class="hl">เมื่อเด่น: ${esc(PSTRONG[n][0])}<br>เมื่ออ่อน: ${esc(PSTRONG[n][1])}</div>
<div class="foot" style="margin-top:7px">ภาค ๑ หน้า ๓๕–๓๗</div></div>` : ""}
${tps.length ? `<div class="card"><h2>เรื่องที่เลขนี้เป็นตัวหลัก</h2>${tps.map(s => topicLine(s, ch)).join("")}</div>` : ""}`, null, BAR_BACK);
}

