const pdGrp = m => (m >= 5 && m <= 7 ? 0 : m >= 8 && m <= 10 ? 1 : m === 11 || m === 12 || m === 1 ? 2 : 3);
const pdCell = s => { const [n, t, g] = s.split("|"); return { n, t, g: g === "g" ? 1 : g === "b" ? -1 : 0 }; };
const PD_TONE = { 1: ["ไปทางดี", "g"], 0: ["กลาง ๆ", ""], "-1": ["ไปทางเสีย", "b"] };
const pdTone = g => `<span class="${PD_TONE[g][1]}">${PD_TONE[g][0]}</span>`;
// คู่ที่ลงเลขเดียวกัน: เดือน ๑–๕ คู่ ๘–๑๒ ที่เรือนตนุ (หน้า ๗๘) · ปีชวด–มะโรง คู่ มะแม–กุน ที่เรือนมรณะ (หน้า ๘๐)
const pdPair = n => (n >= 1 && n <= 5 ? n + 7 : n >= 8 && n <= 12 ? n - 7 : 0);
function pdRead(ch) {
  const m = ch.lunar.month, y = ch.naksat, d = ch.dayIdx;
  const ym = pdCell(PD_YM[y - 1][pdGrp(m)]), yd = pdCell(PD_YD[y - 1][d]);
  const lv = ym.g > 0 && yd.g > 0 ? 1 : ym.g < 0 && yd.g < 0 ? -1 : 0;   // กฎสรุปหน้า ๘๗
  const head = lv > 0 ? "พื้นดวงเดิมดีมาก" : lv < 0 ? "พื้นดวงเดิมเสียมาก" : "พื้นดวงเดิมปานกลาง";
  const why = lv > 0 ? "ลักษณะตามเดือนเกิดและวันเกิดไปทางดีด้วยกัน สร้างความเป็นปึกแผ่นให้ชีวิตได้ง่าย"
    : lv < 0 ? "ลักษณะตามเดือนเกิดและวันเกิดไปทางเสียด้วยกัน การสร้างความเป็นปึกแผ่นต้องพบความทุกข์ยากลำบาก"
    : "ลักษณะตามเดือนเกิดและวันเกิดมีทั้งดีและเสียคละกัน ไม่ง่ายไม่ยากเกินไป อยู่ที่ความมานะพยายาม";
  return { m, y, d, ym, yd, lv, head, why, cls: lv > 0 ? "g" : lv < 0 ? "b" : "", mp: pdPair(m), yp: pdPair(y) };
}

// ---- วิถีชีวิตตามยามเวลาเกิด (หน้า ๘๘–๑๐๐) · ยามละชั่วโมงครึ่ง กลางวัน ๘ ยาม กลางคืน ๘ ยาม ----
const YAM_TIME = [["06.01–07.30", "07.31–09.00", "09.01–10.30", "10.31–12.00", "12.01–13.30", "13.31–15.00", "15.01–16.30", "16.31–18.00"], ["18.01–19.30", "19.31–21.00", "21.01–22.30", "22.31–24.00", "24.01–01.30", "01.31–03.00", "03.01–04.30", "04.31–06.00"]];
const PD_YAM = [
  [["มีสติปัญญาปราดเปรื่อง แรกเกิดเลี้ยงยาก ชะตามักมีศัตรูเบียดเบียน แต่มักมีอำนาจและทรัพย์สิน ได้พึ่งคู่ครอง มีหลักฐานเพราะคู่ครอง", "มีวาทศิลป์ดี เจ้าปัญญา ชอบสังคม มักมีเคราะห์เกี่ยวกับน้ำและที่สูง ต้องจากถิ่นที่กำเนิด", "ว่ายากสอนยาก เอาแต่ใจตัวเองเป็นใหญ่ มักเดือดร้อนเพราะมิตรสหาย เยาว์วัยเลี้ยงยาก", "อาภัพญาติ ชะตามักประสบการพลัดพราก ไปได้ดีในต่างถิ่นกำเนิด เป็นชะตาเสียทรัพย์", "แรกเกิดได้ผู้อื่นเลี้ยงจึงจะดี มีปัญหาด้านคู่ครอง มักประสบเรื่องอัคคีภัย มีทุกข์เพราะคนใกล้ชิด", "มีตำหนิของไฟและปาน มีความรู้ความสามารถด้านการสอน มีวาสนา ประสบความสำเร็จในชีวิต มีเกียรติสูง", "ดื้อ ไม่ยอมคน จิตใจกล้าหาญ ตัดสินใจเร็ว ชอบเป็นหัวหน้าคน ลำบากเพราะมิตรสหายและบริวาร ญาติพี่น้องพึ่งพาอาศัยได้ยาก", "แรกเกิดเลี้ยงยาก ขี้โรคตั้งแต่เด็ก ทะนงตน ชอบอวดรู้ มักเก่งทางช่าง ชอบวางอำนาจ"],
   ["มีวาสนาดี เด่นด้านสติปัญญาและความรู้ แต่เลี้ยงยากเมื่อวัยเยาว์ ชะตาชีวิตมีลาภยศ", "มีตำหนิไฟปานในร่มผ้า มีน้ำใจ มีวาสนาด้านการงาน รู้หลักวิชาการ จะได้เป็นใหญ่และมีลาภยศเงินทอง", "อาภัพ ต้องพลัดพรากจากครอบครัว ต้องก่อร่างสร้างฐานะด้วยตนเอง มักประสบความเดือดร้อนเรื่องคดีความ", "แรกเกิดให้ลาภแก่ครอบครัว ชีวิตจะประสบอุบัติเหตุทางน้ำ เอาตัวรอดเก่ง มักได้รับการอุปถัมภ์ค้ำชูจากญาติมิตร", "มักถูกโรคภัยเบียดเบียน เข้ากับผู้อื่นยาก มักประสบปัญหาด้านการงาน ใจกล้าเกินขอบเขต มักเสียหายเพราะเชื่อคนง่าย", "มักประสบภัยเกี่ยวกับที่อยู่อาศัย ต้องก่อร่างสร้างฐานะด้วยตนเอง ใจแข็ง อดทน มานะ ต้องต่อสู้บากบั่นจึงเอาตัวรอดได้", "มักมีเหตุเพราะปาก โทสะร้าย อาฆาต มักเดือดร้อนเพราะคบคนพาล ต้องพึ่งตนเอง", "มักมีตำหนิไฟปานตามส่วนต่างๆ ของร่างกาย ต้องให้ผู้อื่นเลี้ยงจึงจะเจริญดี เจ้าทุกข์ เก่งทางช่าง รู้หลักวิชาการ หลักแหลม เป็นที่นับหน้าถือตา ตั้งตัวได้ด้วยความสามารถของตัวเองเป็นหลัก"]],
  [["ต้องจากถิ่นกำเนิดแต่เยาว์วัย มักเดินทางบ่อย ใจร้อน ชอบใฝ่หาความรู้ มักใหญ่ใฝ่สูง", "เมื่อน้อยมักต้องจากบิดามารดา ญาติพี่น้องพึ่งพาได้ยาก มักได้ดีเพราะผู้อื่นชุบเลี้ยง มีวาสนาด้านทรัพย์สินเงินทอง", "มีบุญดีแต่กำเนิด มีวาสนาด้านความอุปถัมภ์ค้ำชู ชอบเป็นผู้นำ ชะตามักมีความสุข มีบริวารมาก", "ต้องจากถิ่นฐานกำเนิดจึงจะเจริญดี เยาว์วัยมักเลี้ยงยาก ทรัพย์สินเงินทองมักรั่วไหล ชีวิตต้องพึ่งลำแข้งของตัวเองเป็นส่วนใหญ่", "มีความอดทนสูง ชอบพึ่งพาตนเอง มีปากเป็นเอก ช่างเจรจา ปัญญาดี ชอบแสวงหาการศึกษาและเรียนรู้อยู่เสมอ", "ดวงชะตาแข็ง มักแคล้วคลาดจากภยันตรายต่างๆ มีความสำคัญในตัวเอง จะได้ดีด้วยความสามารถของตัวเอง", "มักโชคดีเพราะผู้อื่นชุบเลี้ยงอุปถัมภ์ ชอบผจญภัย นิสัยแข็งกร้าว ไม่ง้อใคร มักเสียเพราะปาก แต่มากด้วยความกตัญญู", "แต่เล็กมักเลี้ยงยาก ถ้าได้ผู้อื่นชุบเลี้ยงจะได้ดีมีวาสนา ดีด้านผู้อุปถัมภ์ค้ำชู มักแคล้วคลาดจากศัตรู"],
   ["อาภัพเมื่อเยาว์วัย แต่ได้ดีเมื่อเติบใหญ่ ชอบการสังคม เป็นที่นับหน้าถือตา หากจากถิ่นกำเนิดจะเจริญรุ่งเรืองกว่าอยู่ภูมิลำเนาเดิม", "ชะตาแข็งกว่าพี่น้องท้องเดียวกัน อยู่กับบิดามารดามักเลี้ยงยาก เมื่อเล็กมักเจ็บไข้ได้ป่วย มักต้องพึ่งพาตนเอง ชอบใฝ่หาความรู้ มีผู้อุปถัมภ์ดี", "มักได้ดีเพราะผู้อื่นชุบเลี้ยง มีศัตรูคอยเบียดเบียนอยู่เรื่อยๆ จะได้คู่ครองเป็นคนมีทรัพย์ แต่มักอาภัพบริวาร", "อาภัพเมื่อเยาว์วัย ต้องต่อสู้ดิ้นรนด้วยตนเอง มักพลัดพรากจากวงศ์ญาติ ชะตาพลิกผันดีขึ้นเมื่อเติบใหญ่ บริบูรณ์ด้วยทรัพย์สิน ฐานะมั่นคง", "ชะตากำพร้าไม่บิดาก็มารดา หรือพลัดพรากจากกันตั้งแต่เยาว์วัย มีบุญจะได้ผู้อุปถัมภ์ค้ำชู มีมานะ เติบใหญ่มีความมั่นคงทางฐานะการเงิน", "เลี้ยงยากแต่กำเนิด วัยเยาว์ลำบาก เอาแต่ใจตัวเป็นใหญ่ เชื่อคนยาก แต่มีความสามารถในตัวเอง รอบรู้กิจการดี ตั้งตัวได้ด้วยตนเอง", "เมื่อกำเนิดบิดามารดาจะร่ำรวย มีบุญวาสนา มีผู้อุปถัมภ์มาก มียศฐาบรรดาศักดิ์ เป็นผู้มีชะตาสูง", "มักต้องพรากจากถิ่นฐานกำเนิดจึงจะเจริญดี เยาว์วัยชีวิตมักขลุกขลัก ใจร้อน มานะพยายามสูง ชอบพึ่งพาตนเอง เติบใหญ่เป็นที่ยกย่องนับถือของคนทั่วไป"]],
  [["มีผู้ให้ความอุปถัมภ์ค้ำชูดี มีความสามารถหลายด้าน แต่จิตใจอ่อนไหว เติบใหญ่มียศศักดิ์และฐานะมั่นคง", "มีวาสนา จะได้ดีกว่าวงศาคณาญาติ มีความมานะอุตสาหะ บริวารมาก มั่นคงทางทรัพย์สิน", "เมื่อเล็กต้องห่างเหินจากบิดามารดา จิตใจกล้าแข็ง ไม่ง้อใคร ต้องพึ่งตนเอง มักได้ดีมีฐานะมั่นคงเมื่อบั้นปลายชีวิต", "ต้องเหน็ดเหนื่อย อยู่ไม่ค่อยติดที่ ปากกล้า ชอบงานท้าทาย ไม่เกรงกลัวผู้ใด มีศีลธรรมน้อย แต่จะได้ดีเมื่อบั้นปลายเช่นกัน", "จิตใจเด็ดเดี่ยว มักถือความคิดเห็นของตนเป็นใหญ่ มากชู้หลายเมีย ต้องสร้างฐานะด้วยตนเอง", "ต้องต่อสู้ดิ้นรนตั้งแต่วัยเยาว์ ชีวิตพบความเดือดร้อนต่างๆ นานา เอาตัวรอดเก่ง หาทรัพย์คล่อง แต่เงินทองมักรั่วไหล", "มักได้ดีเพราะผู้อื่นชุบเลี้ยง ชอบงานอาสา ใจนักเลง เป็นที่ชมชอบของผู้ใหญ่ รับราชการจะได้ดีมีความก้าวหน้า", "ร่างกายแข็งแรง กล้าได้กล้าเสีย ใจบุญ กว้างขวาง มักได้รับมรดกตกทอด มียศศักดิ์"],
   ["จิตใจโอบอ้อมอารี ความสามารถสูง มั่งมี ชีวิตไม่ตกอับ เป็นที่นิยมในวงสังคมทั่วไป", "มักได้ดีเพราะผู้อื่นอุปถัมภ์ค้ำจุน มั่นใจในตัวเองสูงเกินควร มักเอาแต่ใจตนเป็นใหญ่ ได้ดีเพราะตัวเอง", "เยาว์วัยสุขภาพไม่สู้แข็งแรงนัก ได้ญาติพี่น้องเป็นที่พึ่ง มักถูกเบียดเบียนด้วยโรคภัยไข้เจ็บ", "มีบุญแต่กำเนิด รอบรู้ในกิจการทั้งปวง มีหน้ามีตาในวงสังคม ฐานะมั่นคง", "ชอบงานอาสา อดทนสูง มักได้ดีเพราะผู้อื่นอุปถัมภ์ เงินทองมักรั่วไหล", "จิตใจแข็งกร้าว รอบรู้ดี แต่มักมีภัยเพราะปากเป็นเหตุ", "เจ้าทุกข์ คิดมากเกินเหตุ เยาว์วัยมักต้องพลัดพรากจากครอบครัว จิตใจโอบอ้อมอารี วาจาดี เติบใหญ่มียศศักดิ์", "จิตใจกล้าหาญ มีความรู้ความสามารถรอบตัว เติบใหญ่จะได้ดี มีตำแหน่งการงานสูง ฐานะมั่นคง"]],
  [["เก่งทางงานช่าง งานฝีมือ มีความรู้รอบตัวดี เคร่งครัดศีลธรรม เหมาะเป็นครูบาอาจารย์ ฐานะมั่นคง", "มีบุญวาสนาแต่กำเนิด รอบรู้ในหลักธรรม รักความสงบ ประสบความสำเร็จในหน้าที่การงานดี มีลาภยศเงินทอง", "มีไฟปานหรือตำหนิแต่กำเนิด จิตใจกล้าแข็ง ชีวิตมักหย่าร้าง มักมีภัยเพราะต้องคดีความ", "เจริญวัยเพราะผู้อื่นอุปถัมภ์ชุบเลี้ยง ลำบากตอนเยาว์วัย เติบใหญ่ได้ดีด้วยลำแข้งของตัวเอง แต่มักมีภัยเพราะศัตรูอยู่เนืองๆ", "มักพลัดพรากจากครอบครัวตั้งแต่เยาว์วัย ต้องพึ่งพาตนเองเมื่อเติบใหญ่ ฝักใฝ่การแสวงหาความรู้ มานะพยายามดี มีคนนับหน้าถือตาในสังคม", "มักได้ทุกข์เพราะโรคภัยเบียดเบียน แต่มีวาสนาดี รอบรู้วิชาการ ฐานะมั่นคง", "มีวาสนาด้านรูปโฉม เป็นที่ต้องตาของคนทั้งหลาย มีผู้อุปถัมภ์ดี เชี่ยวชาญการช่าง ทรัพย์สินบริบูรณ์", "เยาว์วัยมีทุกข์ภัยจากโรคาพยาธิ เติบใหญ่รอบรู้ในหลักวิชาการ รับราชการดี มีชื่อเสียงเป็นที่นับหน้าถือตาของคนทั่วไป"],
   ["มีบุญวาสนาด้านทรัพย์สินเงินทองตั้งแต่เล็ก ชอบแสวงหาวิชาความรู้ การสังคมดี มีบริวารมาก", "ประสบความสำเร็จในกิจการงานดี มั่นคงทางทรัพย์สิน หากรับราชการจะได้เป็นใหญ่เป็นโต อายุยืน", "มีตำหนิตามร่างกาย วัยเยาว์มักต้องพลัดพรากจากครอบครัว จะได้ดีเพราะผู้อื่นอุปถัมภ์ค้ำชู สุขสบายในบั้นปลาย", "มีบุญวาสนาแต่กำเนิด สามารถรอบตัว รู้หลักวิชา ทำกิจการใดมักเจริญดี มั่งมีสินทรัพย์ ฐานะมั่นคง", "รูปโฉมงาม จิตใจโอบอ้อมอารี ประสบความสำเร็จในอาชีพพ่อค้าวาณิช กว้างขวางในสังคม ฐานะดี", "อาภัพ ต้องดิ้นรนตั้งแต่อายุวัยน้อย ต้องพึ่งพาตนเอง จะเจริญรุ่งเรืองได้ในต่างถิ่นฐานบ้านเกิด", "กล้าแข็ง นักต่อสู้ จิตใจกล้าหาญ ต้องสร้างฐานะด้วยลำแข้งตนเอง มักมีภัยเพราะต้องคดีความ", "ต้องต่อสู้ดิ้นรนในวัยเยาว์ มีไหวพริบดี ปัญญาไว รู้หลักนักปราชญ์ เติบใหญ่มีคนนับหน้าถือตา ฐานะมั่นคงดี"]],
  [["มีไฝฝ่านหรือตำหนิ มีตระกูลดี รับราชการจะได้เป็นใหญ่ มีทรัพย์สินมั่นคง", "มีบุญแต่กำเนิด มีอำนาจทางยศศักดิ์ มิฉะนั้นก็เป็นชะตาเศรษฐี มีบริวารมาก", "ความทะเยอทะยานสูง ชอบเป็นผู้นำ มีโชคลาภเนืองๆ ใจร้อน ทำกิจการใดมักจะเจริญไว", "รูปโฉมเป็นที่ต้องตาคนทั้งหลาย มิตรสหายมาก แต่นิสัยเจ้าชู้ และเป็นผู้ใฝ่หาทรัพย์เก่ง", "ปากเป็นเอก ได้ดีเพราะการเจรจา ถือความคิดตนเป็นใหญ่ สติปัญญาดี เอาตัวรอดเก่ง", "พบความขัดสนในเยาว์วัย ย้ายถิ่นที่พำนักบ่อยครั้ง ไม่ค่อยกระตือรือร้น พอใจตามฐานะที่เป็นอยู่ของตนเอง", "ชอบสู้ชีวิต จิตใจกล้าหาญ สามารถในการประกอบกิจการดี มักมีศัตรูเบียดเบียนและมีภัยเพราะคดีความ", "มีบุญวาสนาเพราะผู้อื่นอุปถัมภ์ มีอำนาจในตัวเอง รับราชการจะเป็นใหญ่ในตำแหน่งหน้าที่ ฐานะมั่นคง"],
   ["มีวาสนา รอบรู้ในหลักวิชาการดี เหมาะรับราชการ มีสมบัติมาก", "ต้องย้ายถิ่นที่อาศัยบ่อย ชีวิตมักมีอุปสรรค ต้องสร้างฐานะด้วยตนเอง มีภัยเพราะคนใกล้ชิด", "เกิดในตระกูลดี ความรู้สูง อุดมด้วยลาภยศ แต่มีภัยเพราะศัตรูคิดร้าย มักแคล้วคลาดภัย ฐานะมั่นคง", "กล้าหาญ ชอบต่อสู้ด้วยลำแข้งตัวเอง ไม่ยอมคน มีไหวพริบชั้นเชิงสูง มีภัยเพราะศัตรู หลักฐานมั่นคงดี", "ไม่ชอบอยู่นิ่งเฉย อยู่ไม่ติดที่แต่กำเนิด ชอบท่องเที่ยว มั่นใจในตัวเองเกินควร โทสะร้าย มักมีศัตรู", "เป็นคนเจ้าสำราญ ทรัพย์สินบริวารมาก รอบรู้หลักวิชา กว้างขวาง รับราชการจะได้เป็นใหญ่", "มีวาสนา เกิดในตระกูลดี รักความยุติธรรม ใจคอกว้างขวาง สังคมดี เป็นที่นับหน้าถือตา สมบัติมาก", "มีวาสนาในทรัพย์สมบัติ ทำกิจการใดมักประสบผลดี ฝักใฝ่ด้านการกุศล มีบริวารมาก"]],
  [["ความรอบรู้ เจ้าเสน่ห์ เป็นที่พึงใจของคนทั้งหลาย มักแคล้วคลาดจากภยันตราย บริวารมาก รับราชการดี", "มีวาสนาแต่กำเนิด มั่งมี ชอบแสวงหาความรู้ เป็นนักวิชาการหรือนักศิลปศาสตร์ รักสนุก เด่นในสังคม", "ได้รับความทุกข์ยากในวัยเยาว์ แต่ได้ดีเพราะมีผู้อุปถัมภ์ ต้องจากถิ่นฐานกำเนิดไปเจริญในต่างถิ่น ถ้าเป็นพ่อค้าจะมั่นคงดี", "ต้องพลัดพรากจากครอบครัวตั้งแต่วัยเด็ก ต้องต่อสู้ชีวิตด้วยลำแข้งตัวเอง สร้างฐานะได้ดีในวัยกลางคน", "มีทุกข์เพราะโรคภัยไข้เจ็บ แต่มีผู้อุปถัมภ์ดี รักการค้นคว้าในวิทยาการต่างๆ ชอบแสวงหาทรัพย์ หลักฐานมั่นคงดีตั้งแต่วัยหนุ่มสาว", "นิสัยขยันขันแข็ง ต่อสู้ชีวิตทุกรูปแบบ ค่อนข้างใจร้อน มักมีศัตรู รักงานด้านศิลปศาสตร์", "มีวาสนาดีในเยาว์วัย ถึงวัยหนุ่มมักมีเคราะห์กรรมจากภัยต่างๆ เช่น การศึกษาและงานอาชีพ แต่มีผู้ให้ความช่วยเหลืออุปถัมภ์ สร้างฐานะได้ในภายหลัง", "ในวัยเด็กได้รับอุบัติภัยเพราะน้ำ หรือมีภัยจากที่สูง ชะตาแคล้วคลาด มีวาสนาเมื่อเติบใหญ่ รับราชการจะเจริญก้าวหน้า ฐานะมั่นคง"],
   ["สำอาง ชอบความสบาย มีวาสนาด้านทรัพย์สินการเงิน สังคมกว้างขวาง รับราชการดี รู้หลักวิชาการหลายด้าน", "ต้องจากถิ่นฐานกำเนิด เจริญในต่างถิ่น ชีวิตจะได้ดีมักต้องพึ่งพาความสามารถตัวเอง ขยันหมั่นเพียร ไม่ชอบดูดาย จึงมีผู้นิยมชมชอบ", "นิสัยมุทะลุ ใจร้อน แต่มีน้ำใจดี กล้าหาญ ชอบผจญภัยและการเดินทาง สร้างฐานะได้มั่นคงด้วยตัวของตัวเอง", "มีวาสนาแต่กำเนิด สมบูรณ์พูนสุข มักแคล้วคลาดจากภยันตราย เป็นพ่อค้าจะมั่งมี เป็นที่เชื่อถือในวงสังคม", "ชีวิตราบรื่นจากวัยเด็กถึงวัยหนุ่มสาว แต่จะมีอุปสรรคในวัยกลางคน มีศัตรูในวงงาน มักต้องรับภาระมากในเรื่องญาติพี่น้อง ฐานะมั่นคงในบั้นปลาย", "อ่อนแอในวัยเยาว์ มีโรคพยาธิเบียดเบียน เติบใหญ่ชีวิตจึงจะเปลี่ยนแปลงดีขึ้น รอบรู้ด้านวิชาการ กว้างขวางในวงสังคม", "ต้องเดินทางบ่อย ไม่ชอบอยู่ติดที่ นิสัยใจร้อน เจรจาเป็นที่ถูกใจคนทั้งหลาย สร้างฐานะได้เพราะมีผู้อุปถัมภ์", "มีภัยจากที่สูง ในวัยเด็กซุกซนมาก ชอบการสมาคม มีเสน่ห์ในตัวเอง เจ้าปัญญา สร้างฐานะได้มั่นคงเพราะความอุตสาหะ"]],
  [["เหนื่อยง่าย ชอบความสะดวกสบาย ทำการใดมักไม่ยืนนาน มีภัยเพราะวาจา แต่สามารถสร้างฐานะมั่นคงได้เมื่อเจริญวัย", "กล้าได้กล้าเสีย ใจแข็งแต่ใจกว้าง นิสัยมักอวดรู้ ชอบใช้ชีวิตอย่างคุ้มค่า รู้เท่าทันผู้อื่น ชอบการสังคม สร้างฐานะได้ด้วยความอุตสาหะของตัวเอง", "ห่างเหินจากญาติพี่น้อง ต้องพึ่งพาตนเอง ไม่ง้อคน มีปัญญาหลักแหลม เติบใหญ่จะมีฐานะเป็นปึกแผ่น", "ต้องพลัดพรากจากครอบครัวเมื่ออายุยังน้อย แต่จะได้ผู้อุปถัมภ์ชุบเลี้ยง วัยหนุ่มสาวต้องต่อสู้ชีวิต ฐานะดีเพราะความหมั่นเพียร", "อาภัพ ญาติพี่น้องพึ่งพาได้ยาก มักไปเจริญในต่างถิ่นต่างแดน ชอบท่องเที่ยว จะสร้างฐานะเป็นปึกแผ่นได้ต้องใช้ความขยันหมั่นเพียรและอดทนเป็นที่ตั้ง", "อุตสาหะมานะดี นิสัยชอบสันโดษ แต่สุขุมรอบคอบ รอบรู้ทางวิชาการ มักมีภัยเพราะถูกหักหลัง ฐานะมั่นคงดี", "จะได้ดีเพราะผู้อื่นชุบเลี้ยง ใจร้อน ไม่ยอมคน มักมีภัยจากคดีความ บากบั่นในการสร้างฐานะจนมีความเป็นปึกแผ่นได้", "ขี้โรคในวัยเด็ก เติบใหญ่จึงสมบูรณ์แข็งแรง รอบคอบ ทำการใดมักต้องพึ่งพาตนเอง จะมีฐานะดีเมื่อถึงวัยผู้ใหญ่"],
   ["ขี้กังวล มองโลกในแง่ร้าย แต่รอบคอบ ทำการใดมักต้องเผชิญอุปสรรคก่อนจึงสำเร็จด้วยดี มิตรมากแต่พึ่งได้ยาก ชีวิตจะพบความสำเร็จได้เพราะความมานะของตนเอง", "มีวาทศิลป์ดี ชอบค้นคว้าหาความรู้ใส่ตัว มักประสบความสำเร็จจากงานที่ใช้สมองหรือสติปัญญา เจ้าหลักการ ฐานะมั่นคงดี", "ต้องพลัดพรากจากครอบครัว พึ่งตนเองตั้งแต่เยาว์วัย อุดมด้วยผู้อุปถัมภ์ค้ำชู บากบั่น ขยันขันแข็งในการสร้างฐานะให้แก่ตัวเอง", "สุขภาพดีแต่กำเนิด นิสัยหนักแน่น ซื่อตรง เก่งด้านรัฐศาสตร์ การปกครอง รับราชการจะเจริญดี", "มีผู้อุปถัมภ์ดีตั้งแต่เยาว์วัย มักมีโรคประจำตัว เพื่อนมาก กว้างขวางในสังคม มักมีคู่หลายครั้ง สร้างฐานะได้มั่นคงเพราะมีผู้อุปถัมภ์", "มีเสน่ห์ในตัวเอง สังคมเก่ง ถนัดด้านเศรษฐศาสตร์ ชอบงานประเภทสังคมสงเคราะห์ มักได้ดีมีผลประโยชน์จากการเข้าสังคม", "นักผจญภัย ชอบการเดินทาง ชีวิตมักประสบอุปสรรคในหน้าที่การงาน มักท้อแท้ผิดหวังเสียก่อน แต่จะสร้างฐานะได้ในบั้นปลาย", "ถืออารมณ์ตนเองเป็นใหญ่ แต่เฉลียวฉลาด รอบรู้ อุตสาหะในอาชีพการงาน เป็นคนเจ้าทรัพย์"]]
];
function yamRead(ch) {
  if (!ch.hasTime || !ch.born) return null;
  const mm = ch.born.getHours() * 60 + ch.born.getMinutes();
  const isDay = mm > 360 && mm <= 1080;                    // ๐๖.๐๑–๑๘.๐๐ = ยามกลางวัน
  const off = isDay ? mm - 361 : (mm >= 1081 ? mm - 1081 : mm + 359);
  const half = isDay ? 0 : 1, i = clamp(Math.floor(off / 90), 0, 7);
  return { half, halfTxt: isDay ? "กลางวัน" : "กลางคืน", i, no: i + 1,
           time: YAM_TIME[half][i], text: PD_YAM[ch.dayIdx][half][i] };
}

// ---- ดิถีกำเนิด (หน้า ๑๐๑–๑๐๕) · เลขทั้งหมดยกจากตำรา ไม่ใช่ตารางฤกษ์ที่สกัดจากปฏิทิน ----
const DG_UP = "มักได้รับการยกย่องสรรเสริญจากผู้อื่น มีความดีเด่นในสังคม มีบริวารมาก มีความสุข อุดมไปด้วยญาติพี่น้อง มั่งคั่งร่ำรวย มีคุณงามความดี มีศีลธรรม มีเสน่ห์ ค่อนข้างเจ้าชู้";
const DG_DOWN = "ชีวิตมักต้องเหน็ดเหนื่อย ต่อสู้ดิ้นรนด้วยตนเอง ไม่มีใครเอาใจใส่ เก็บตัวไม่เป็นที่รู้จักของสังคม ซื่อตรงและมีความกตัญญูต่อบุพการี แต่มักเป็นศัตรูกับญาติพี่น้อง";
const DG_MASUN = { 5: 6, 6: 4, 7: 8, 8: 6, 9: 4, 10: 8, 11: 10, 12: 12, 1: 2, 2: 10, 3: 12, 4: 2 };   // ดิถีมหาสูญ ตามเดือนเกิด (หน้า ๑๐๑)
const DG_DAY = [   // ตามวันเกิด อาทิตย์ → เสาร์ (หน้า ๑๐๒–๑๐๕)
  { n: "ดิถีพิฆาต", k: [12, 11, 7, 3, 6, 9, 8], t: "มีเกณฑ์ชะตาที่มักเกิดเหตุเภทภัยและภยันตรายต่าง ๆ มากระทบวิถีชีวิตได้ง่าย" },
  { n: "วันทรธึก", k: [4, 6, 1, 3, 8, 7, 1], t: "มักถูกกล่าวหา ลบหลู่ ติเตียน ใส่ร้าย" },
  { n: "วันทักทิน", k: [12, 11, 10, 9, 8, 7, 6], t: "ทำการสิ่งใดมักอยู่ไม่นาน จะล้มเลิกผิดพลาด ชีวิตคู่มักมีการล้มเลิกหย่าร้าง" },
  { n: "วันอัคนีโรธ (โลกาวินาศ)", k: [4, 6, 10, 3, 8, 9, 1], t: "ชีวิตมักมีอุปสรรคกีดขวาง มักประสบอุบัติเหตุด้วยไฟ" },
  { n: "วันทินสูรย์", k: [5, 2, 8, 3, 1, 9, 8], t: "ทำการสิ่งใดมักไร้ผล เกิดเรื่องเกิดเหตุร้าย" },
  { n: "วันกาลกิณี", k: [5, 6, 15, 8, 1, 2, 10], t: "ชีวิตมักมีอุปสรรค มีศัตรูปองร้าย" }
];
function dithiRead(ch) {
  const L = ch.lunar, up = L.phase === "ขึ้น", kham = L.kham, m = L.month, d = ch.dayIdx;
  const hits = [];
  if (DG_MASUN[m] === kham) hits.push({ n: "ดิถีมหาสูญ", w: `เดือน ${TH(m)} คู่กับ ${TH(DG_MASUN[m])} ค่ำ`, t: "มีเกณฑ์ชะตาที่มักไม่ราบรื่น มีอุปสรรคและความสูญเสียเกิดขึ้นได้ง่าย" });
  if (kham === m) hits.push(up ? { n: "กระทิงวัน", w: `ขึ้น ${TH(kham)} ค่ำ เท่ากับเลขเดือนเกิด`, t: "มีเกณฑ์ชะตาที่มักวุ่นวาย สับสน วิถีทางการดำเนินชีวิตขึ้น ๆ ลง ๆ ได้ง่าย" }
                                : { n: "วันผีโขมด", w: `แรม ${TH(kham)} ค่ำ เท่ากับเลขเดือนเกิด`, t: "มีเกณฑ์ชะตาที่มักพบความอับเฉา โศกเศร้าเสียใจได้ง่าย" });
  DG_DAY.forEach(o => { if (o.k[d] === kham) hits.push({ n: o.n, w: `วัน${DAYS[d]} คู่กับ ${TH(kham)} ค่ำ`, t: o.t }); });
  const better = up ? kham >= 7 : kham <= 8;
  const tier = up ? (better ? "ขึ้น ๗ ค่ำ ถึง ๑๕ ค่ำ ตำราว่าชะตามักดีกว่าผู้เกิดขึ้น ๑ ถึง ๖ ค่ำ" : "ขึ้น ๑ ถึง ๖ ค่ำ ตำราว่ารองจากผู้เกิดขึ้น ๗ ถึง ๑๕ ค่ำ")
                   : (better ? "แรม ๑ ถึง ๘ ค่ำ ตำราว่าชะตามักดีกว่าผู้เกิดแรม ๙ ค่ำขึ้นไป" : "แรม ๙ ค่ำขึ้นไป ตำราว่ารองจากผู้เกิดแรม ๑ ถึง ๘ ค่ำ");
  return { up, kham, m, d, hits, better, side: up ? "ข้างขึ้น" : "ข้างแรม", sideTxt: up ? DG_UP : DG_DOWN, tier };
}

// ---- การ์ดรอบ ๓ ----
function pdCard(ch) {
  if (ch.synth || !ch.lunar) return "";
  const R = pdRead(ch), nm = c => (c.n ? `<b>${esc(c.n)}</b> · ` : "");
  return `<div class="card"><h2>พื้นดวงตำรับโบราณ <span>ตำรา ภาค ๑ หน้า ๗๖–๘๗</span></h2>
<div class="kv">• <b>สรุปตามกฎหน้า ๘๗</b> = <span class="${R.cls}">${esc(R.head)}</span> — ${esc(R.why)}</div>
<div class="kv">• <b>ปี × เดือนเกิด</b> ${esc(PD_ANI[R.y - 1])}เกิดเดือน ${PD_GRP[pdGrp(R.m)]} = ${nm(R.ym)}${esc(R.ym.t)} (${pdTone(R.ym.g)})</div>
<div class="kv">• <b>ปี × วันเกิด</b> ${esc(PD_ANI[R.y - 1])}เกิดวัน${esc(DAYS[R.d])} = ${nm(R.yd)}${esc(R.yd.t)} (${pdTone(R.yd.g)})</div>
<details><summary>คำพยากรณ์วันเกิด เดือนเกิด และปีเกิด (เต็ม)</summary><div class="foot">
<b>วัน${esc(DAYS[R.d])}</b> — ${esc(PD_DAY[R.d])}<br><br>
<b>เดือน${esc(LMON_TH[R.m - 1])} (${TH(R.m)})</b> — ${esc(PD_MON[R.m - 1])}<br><br>
<b>ปี${esc(NAKSAT[R.y - 1])}</b> — ${esc(PD_YR[R.y - 1])}
</div></details>
<details><summary>คู่เดือนและคู่ปีที่ลงเลขเดียวกัน</summary><div class="foot">
${R.mp ? `เดือน ${TH(R.m)} ลงเลขที่<b>เรือนตนุ</b>เท่ากับเดือน ${TH(R.mp)} (หน้า ๗๘) — ผังตรงนั้นเท่ากันแต่วิถีชีวิตไม่เหมือนกัน ตำราให้ใช้คำพยากรณ์เดือนเกิดแยกความต่าง`
        : `เดือน ${TH(R.m)} ไม่มีเดือนคู่ — ตำราจับคู่ไว้ ๕ คู่ (๑–๘ ๒–๙ ๓–๑๐ ๔–๑๑ ๕–๑๒) เดือน ๖ และ ๗ จึงลงเลขเรือนตนุไม่ซ้ำเดือนใด`}<br>
${R.yp ? `ปี${esc(NAKSAT[R.y - 1])} ลงเลขที่<b>เรือนมรณะ</b>เท่ากับปี${esc(NAKSAT[R.yp - 1])} (หน้า ๘๐) — ใช้คำพยากรณ์ปีเกิดแยกความต่างเช่นเดียวกัน`
        : `ปี${esc(NAKSAT[R.y - 1])} ไม่มีปีคู่ — ตำราจับคู่ไว้ ๕ คู่ (ชวด–มะแม ฉลู–วอก ขาล–ระกา เถาะ–จอ มะโรง–กุน) ปีมะเส็งและมะเมียจึงลงเลขเรือนมรณะไม่ซ้ำปีใด`}<br>
ตรวจกับผังที่แอปสร้างแล้ว ครบทั้ง ๕ คู่เดือนและ ๕ คู่ปี
</div></details>
<div class="kv" style="color:var(--tx3);font-size:11.5px">ตำรับโบราณแบ่งคนเป็นแบบกว้าง ๆ (วัน ๗ · เดือน ๑๒ · ปี ๑๒) ตำราให้ใช้ประกอบกับฐานกำลังพระเคราะห์และเรือนชะตา ไม่ใช้ตัดสินแทนผัง ส่วนนี้จึงไม่นำไปรวมคะแนนรายเรือนหรือรายเรื่อง</div></div>`;
}
function yamCard(ch) {
  const Y = yamRead(ch);
  if (!Y) return `<div class="card"><h2>วิถีชีวิตตามยามเกิด <span>หน้า ๘๘–๑๐๐</span></h2><div class="kv">ยังไม่ได้กรอกเวลาเกิด — กรอกเวลาแล้วส่วนนี้จะบอกยามเกิดและคำทำนายของยามนั้น (ตำราแบ่งวันละ ๑๖ ยาม ยามละชั่วโมงครึ่ง)</div></div>`;
  const list = PD_YAM[ch.dayIdx][Y.half].map((t, i) => `${i === Y.i ? "<b>" : ""}ยาม ${TH(i + 1)} (${esc(YAM_TIME[Y.half][i])} น.) — ${esc(t)}${i === Y.i ? "</b>" : ""}`).join("<br><br>");
  return `<div class="card"><h2>วิถีชีวิตตามยามเกิด <span>ตำรา ภาค ๑ หน้า ๘๘–๑๐๐</span></h2>
<div class="kv">• <b>ยามเกิด</b> = วัน${esc(DAYS[ch.dayIdx])} ยาม${esc(Y.halfTxt)} ยามที่ ${TH(Y.no)} (${esc(Y.time)} น.)</div>
<div class="kv">• <b>คำทำนาย</b> ${esc(Y.text)}</div>
<details><summary>ทั้ง ๘ ยามของวัน${esc(DAYS[ch.dayIdx])} ยาม${esc(Y.halfTxt)}</summary><div class="foot">${list}</div></details>
<div class="kv" style="color:var(--tx3);font-size:11.5px">ยามใช้วันโหรเช่นเดียวกับผัง เกิด ๐๐:๐๐–๐๖:๐๐ จึงนับเป็นยามกลางคืนของวันก่อนหน้า · ตำรานับยามกลางวัน ๐๖.๐๑–๑๘.๐๐ และยามกลางคืน ๑๘.๐๑–๐๖.๐๐</div></div>`;
}
function dithiCard(ch) {
  if (ch.synth || !ch.lunar || !ch.inTbl) return "";
  const R = dithiRead(ch);
  const hits = R.hits.length
    ? R.hits.map(h => `<div class="kv">• <span class="b">${esc(h.n)}</span> (${esc(h.w)}) — ${esc(h.t)}</div>`).join("")
    : `<div class="kv">• <span class="g">ไม่ตรงเกณฑ์ที่ตำราว่าไม่สู้ดีทั้ง ๘ ข้อ</span></div>`;
  return `<div class="card"><h2>ดิถีกำเนิด <span>ตำรา ภาค ๑ หน้า ๑๐๑–๑๐๕</span></h2>
<div class="kv">• <b>ดิถีเกิด</b> = ${esc(lunarLabel(ch.lunar))} (${esc(R.side)}) · <span class="${R.better ? "g" : ""}">${esc(R.tier)}</span></div>
<div class="kv">• <b>คำทำนายผู้เกิด${esc(R.side)}</b> ${esc(R.sideTxt)}</div>
${hits}
<details><summary>เกณฑ์ทั้ง ๘ ข้อ และที่มา</summary><div class="foot">
ตามเดือนเกิด: <b>ดิถีมหาสูญ</b> (เดือน ${TH(R.m)} = ${TH(DG_MASUN[R.m])} ค่ำ ขึ้นหรือแรมก็ได้) · <b>กระทิงวัน/วันผีโขมด</b> (ดิถีเท่ากับเลขเดือนเกิด ข้างขึ้นเป็นกระทิงวัน ข้างแรมเป็นผีโขมด)<br>
ตามวันเกิด วัน${esc(DAYS[R.d])}: ${DG_DAY.map(o => `<b>${esc(o.n)}</b> ${TH(o.k[R.d])} ค่ำ`).join(" · ")}<br><br>
เลขทั้งหมดยกจากตำราโดยตรง ไม่ใช่ตารางฤกษ์ที่สกัดจากปฏิทิน (การ์ดฤกษ์ด้านบนใช้ตารางปฏิทิน) — เทียบกันแล้ว ๕ ใน ๖ ชุดเป็นชุดเดียวกัน โดย ดิถีพิฆาต ทรธึก ทินสูรย์ กาลกิณี ตรงทั้ง ๗ วัน และ วันทักทิน ของตำราตรงกับแถวที่ปฏิทินเรียก "กาลทัณฑ์" ทั้ง ๗ วัน<br>
ต่างกันจริงชุดเดียวคือ วันอัคนีโรธ (โลกาวินาศ) ตรง ๖ ใน ๗ วัน — วันพุธ ตำราว่า ๓ ค่ำ ปฏิทินว่า ๙ ค่ำ · การ์ดนี้ยึดตำรา
</div></details></div>`;
}

