function s6SnCalc(dayNum, mm, up, kham) {
  const isDay = mm > 360 && mm <= 1080, off = isDay ? mm - 361 : (mm >= 1081 ? mm - 1081 : mm + 359);
  const i = clamp(Math.floor(off / 90), 0, 7), j = clamp(Math.ceil((off - 90 * i + 1) * 60 / 675) - 1, 0, 7), st = isDay ? 5 : 4;
  const big = s6m7(dayNum + st * i), small = s6m7(big + st * j), B = s6Bhumi(!isDay, up, kham), col = [];
  for (let n = 0, k = B.ring.indexOf(small); n < 8; n++, k = s6r8(k + B.dir)) col.push(B.ring[k]);
  return { night: !isDay, i, j, big, small, B, col };
}
