function mpRender(M, e, tab) { return withSim(M.at, () => { const h = mpRender0(M, e, tab); return h && M.sim ? simDecor(h, M.ch, M.sim) : h; }); }   // v3.9.37 หน้าที่สร้างใช้เวลาเดียวกับตอน mpBuild
