      const bar = `<div class="mode tmb" id="mode">${MP_TMODE.map(k => `<a${k === md ? ' class="on"' : ""} href="satta7://cmode?m=${k}">${MP_TLAB[k]}${tv[k] ? `<small class="${SC_CLS[TRV5(tv[k].score)]}">${mkW(tv[k].word)} ${TH(tv[k].score)}</small>` : ""}</a>`).join("")}</div>`;
