function scoreCheck() {
  const out = []; let ok = 0, fail = 0;
  for (const g of GOLDEN_SC) {
    const ch = natalChart({ iso: g.iso, time: null, name: "ตรวจ" });
    if (ch.err) { fail++; out.push(`❌ ${g.iso} ${ch.err}`); continue; }
    const rd = natalRead(ch);
    out.push(`• ${g.iso} (${g.ref})`);
    for (const [k, col, lo, hi, why] of g.want) {
      const got = k === "total" ? rd.self.total : houseRead(k, col, ch).sc.score;
      const lab = k === "total" ? "อัตตะ+ตนุ" : `${houseAt(k, col, ch)} (${B89TH[k] || { day: "ฐาน ๑", month: "ฐาน ๒", year: "ฐาน ๓" }[k] || k})`;
      const pass = got >= lo && got <= hi;
      if (pass) ok++; else fail++;
      out.push(`   ${pass ? "✓" : "✗"} ${lab} ได้ ${TH(got)} · ต้องอยู่ ${TH(lo)}–${TH(hi)} — ${why}`);
    }
  }
  return { ok, fail, text: `ตรงตามตำรา ${TH(ok)}/${TH(ok + fail)} ข้อ\n\n` + out.join("\n") };
}

