    say: [{ h: "อัตตะ", n: 7, sum: 10, sName: "กำลังพระเสาร์" }, { h: "ตนุ", n: 1, heavyHas: ["หินะ"] }, { h: "พันธุ", n: 4, sum: 15 }],
