// ================= ทางเข้าและการนำทาง =================
const parseQ = u => { const o = {}, i = String(u).indexOf("?"); if (i < 0) return o;
  String(u).slice(i + 1).split("&").forEach(kv => { const [k, v] = kv.split("="); if (k) o[decodeURIComponent(k)] = decodeURIComponent(v || ""); }); return o; };

async function openApp() {
  if (NODE) return;
  const wv = new WebView();
  const sleep = ms => new Promise(r => Timer.schedule(ms, false, () => r()));
  const show = async (title, msg) => { await sleep(300); const a = new Alert(); a.title = title; a.message = msg; a.addAction("ตกลง"); await a.present(); };
  const FIX_VP = "(function(){try{var m=document.querySelector('meta[name=viewport]');if(m)m.setAttribute('content','width=device-width, initial-scale=1, minimum-scale=1, shrink-to-fit=no, viewport-fit=cover');document.documentElement.style.zoom='';window.scrollTo(0,0);}catch(e){}})()";
  let ON_NATAL = false, NAV = null, MPC = null, CURHTML = "", XS = null, SIM = null, SIMO = null;   // v3.9.41 SIMO = { m: year|month, msg } · v3.9.37 SIM = เวลาจำลองของผังจำลองชะตา (รอบถัดไป) · null = ตอนนี้
  const getY = async () => { try { return +(await wv.evaluateJavaScript("window.pageYOffset||0", false)) || 0; } catch (e) { return 0; } };
  const loadX = async html => { const sp = mpSplit(html); XS = { nodes: sp.nodes, stack: [], title: ((/<title>([^<]*)</.exec(html) || [])[1] || "").replace(/^.*· /, "") }; await load(sp.html, false); };
  const tabOK = t => ["s1", "s2", "s3", "s4", "s5"].includes(t) ? t : "s1";
  // v3.2.1 เปิดแอป เลือกดวง หรือบันทึกดวง → เริ่มที่แท็บพื้นดวงเสมอ · ระหว่างใช้ สลับแท็บได้ตามปกติ
  const START_TAB = "s1", navReset = () => { NAV = [{ r: "tab", k: START_TAB, y: 0 }]; };
  const navTop = () => NAV[NAV.length - 1];
  // v3.0.0 จำตำแหน่งเลื่อนของหน้าปัจจุบันก่อนเปลี่ยนหน้า (แบบ yam7 ตอนเปลี่ยนขนาดตัวอักษร)
  const saveY = async () => { if (!ON_NATAL || !NAV) return; try { navTop().y = +(await wv.evaluateJavaScript("window.pageYOffset||0", false)) || 0; } catch (e) {} };
  const mpGet = (p, ch) => { const key = [p.id, p.iso, p.time, p.sex, p.order, bigOn() ? 1 : 0, SIM ? "sim" + SIM.getTime() + (SIMO ? SIMO.m + SIMO.msg + "q" + (SIMO.q || "") : "") : Math.floor(Date.now() / 3600000)].join("|");
    if (!MPC || MPC.key !== key) MPC = { key, M: mpBuild(ch, SIM, SIM ? SIMO || { m: "year" } : null) }; return MPC.M; };
  const load = async (html, nat) => { if (SIM && html && html.indexOf('<div class="simb"') < 0) { const p2 = curProfile(), c2 = p2 ? natalChart(p2) : null; html = simDecor(html, c2 && !c2.err ? c2 : null, { at: SIM, m: SIMO ? SIMO.m : "year", msg: "" }); }   // v3.9.41 ทุกหน้าในโหมดจำลองมีแถบ
    ON_NATAL = !!nat; CURHTML = html; await wv.loadHTML(html); try { await wv.evaluateJavaScript(FIX_VP, false); } catch (e) {} };
  const showChart = async restore => {
    const p = curProfile();
    if (!p) return load(formHTML(null, null));
    const ch = natalChart(p);
    if (ch.err) return load(formHTML(p, ch.err));
    if (!NAV) navReset();
    const M = mpGet(p, ch), tab = NAV[0].k;
    let html = mpRender(M, navTop(), tab);
    if (!html) { navReset(); html = mpRender(M, navTop(), NAV[0].k); restore = false; }
    await load(html, true);
    const y = navTop().y; if (restore !== false && y > 0) { try { await wv.evaluateJavaScript(`window.scrollTo(0,${Math.round(y)})`, false); } catch (e) {} }
  };
  const go = async (r, k) => { const t = navTop(), e = { r, k, y: 0 };
    if ((r === "cell" || r === "cmode") && (t.r === "cell" || t.r === "cmode")) NAV[NAV.length - 1] = e; else NAV.push(e);
    await showChart(false); };
  wv.shouldAllowRequest = req => {
    const u = String((req && req.url) || "");
    if (u.indexOf(SCHEME) !== 0) return u.indexOf("about:") === 0 || u.indexOf("data:") === 0;
    const path = u.slice(SCHEME.length).split("?")[0], q = parseQ(u);   // v1.0.1 เลิกนับความยาวสคีมด้วยมือ (เปลี่ยนชื่อสคีมแล้วลิงก์ตายทั้งหน้า)
    (async () => {
      try {
        await saveY(); if (!NAV) navReset();
        if (path !== "sim" && SIMO && SIMO.msg) SIMO = { ...SIMO, msg: "" };   // v3.9.41 ข้อความของปุ่มจำลองแสดงครั้งเดียว
        if (path === "sim") { const p2 = curProfile(), c2 = p2 && natalChart(p2), r = simRoute(c2 && !c2.err ? c2 : null, q, SIM, SIMO);   // v3.9.41 ผังจำลองชะตา
          if (r.off) { SIM = null; SIMO = null; } else { SIM = r.at; SIMO = { m: r.m, msg: r.msg || "", q: r.q || "" }; }
          MPC = null; NAV = NAV.filter(x => x.r !== "p"); if (!NAV.length) navReset();   // หน้าเรื่องย่อยใช้รหัสตามลำดับ อาจไม่ตรงกันข้ามเวลา → กลับหน้าแท็บ/ผัง
          const t = navTop(); if (SIMO && t.r === "tab" && t.k === "s3") NAV[NAV.length - 1] = { ...t, mode: SIMO.m, y: 0 };
          await showChart(false); return; }
        if (path === "x") { const nd = XS && XS.nodes[q.k]; if (nd) { XS.stack.push({ html: CURHTML, y: await getY() }); await load(mpXPage(nd, XS.title), false); } return; }
        if (path === "xup") { const t = XS && XS.stack.pop(); if (!t) { await showChart(); return; } await load(t.html, false); if (t.y > 0) { try { await wv.evaluateJavaScript(`window.scrollTo(0,${Math.round(t.y)})`, false); } catch (e) {} } return; }
        if (path === "new") await load(formHTML(null, null));
        else if (path === "edit") await load(formHTML(curProfile(), null));
        else if (path === "list") await load(listHTML());
        else if (path === "back" || path === "cancel") await showChart();
        else if (path === "pick") { writeJSON(F_STATE, { ...stateGet(), curId: q.id }); navReset(); await showChart(); }
        else if (path === "asknow") { MPC = null; await showChart(); }   // v3.9.32 ข้อตัดสิน 59 ตั้งดวงตามเวลาถามใหม่
        else if (path === "tab") { const t = tabOK(q.t); if (t === "s5") MPC = null; writeJSON(F_STATE, { ...stateGet(), tab: t }); NAV = [{ r: "tab", k: t, y: 0 }]; await showChart(false); }
        else if (path === "tabtop") { NAV = [NAV[0]]; await showChart(); }
        else if (path === "up") { if (NAV.length > 1) NAV.pop(); await showChart(); }
        else if (path === "p" || path === "cell" || path === "hl") await go(path, q.k || "");
        else if (path === "day") await go("day", "");
        else if (path === "cmode" && navTop().r === "tab" && navTop().k === "s3" && MP_TMODE.includes(q.m)) { NAV[NAV.length - 1] = { r: "tab", k: "s3", mode: q.m, y: 0 }; await showChart(false); }
        else if (path === "cmode") { if ((q.m || "natal") === "natal") { if (["cell", "cmode"].includes(navTop().r)) NAV.pop(); await showChart(); } else await go("cmode", q.m); }
        else if (path === "th") { const eff = themeOn() || (q.sys === "light" ? "light" : "dark"); writeJSON(F_STATE, { ...stateGet(), theme: eff === "dark" ? "light" : "dark" }); await showChart(); }   // รอบ 82 สลับมืด/สว่าง
        else if (path === "fs") { writeJSON(F_STATE, { ...stateGet(), big: !stateGet().big }); await showChart(); }   // v1.1.0 สลับขนาดตัวอักษร
        else if (path === "num") { const p2 = curProfile(); const c2 = p2 && natalChart(p2);
          if (c2 && !c2.err && +q.n >= 1 && +q.n <= 7) await loadX(numHTML(c2, +q.n)); else await showChart(); }
        else if (path === "save") {
          let o = null; try { o = JSON.parse(q.d || "{}"); } catch (e) { o = null; }
          const err = o ? validProfile(o) : "อ่านค่าที่กรอกไม่ได้";
          if (err) await load(formHTML(o, err));
          else { saveProfile({ id: o.id || newId(), ...profOf(o, new Date()) }); navReset(); await showChart(); }   // v3.9.27 ข้อตัดสิน 46–47
        }
        else if (path === "menu") {
          // v2.1.2 เมนูเหลือการตั้งค่าและการจัดการดวง · ที่เหลือทั้งหมดอยู่ในหน้าเกี่ยวกับและอ้างอิง
          await sleep(250);
          const m = new Alert(); m.title = `🔮 ${APP}`;
          m.message = menuMsg();   // รอบ 88 ข้อตัดสิน 115
          ["📜 ดวงที่บันทึกไว้", "＋ เพิ่มดวงใหม่", "✎ แก้ดวงที่เลือก", `🔠 ${stateGet().big ? "กลับใช้ตัวอักษรปกติ" : "ใช้ตัวอักษรใหญ่"}`, "ℹ️ เกี่ยวกับและอ้างอิง"].forEach(t => m.addAction(t));
          m.addCancelAction("ปิด");
          const i = await m.present();
          if (i === 0) await load(listHTML());
          else if (i === 1) await load(formHTML(null, null));
          else if (i === 2) await load(formHTML(curProfile(), null));
          else if (i === 3) { writeJSON(F_STATE, { ...stateGet(), big: !stateGet().big }); await showChart(); }
          else if (i === 4) await loadX(aboutHTML(aboutChart(), CHK_RES, {}));
        }
        else if (path === "term") { const p2 = curProfile(), c2 = p2 && natalChart(p2), th = termHTML(c2 && !c2.err ? c2 : null, q.k || "");   // v3.9.38 รอบ 66
          if (XS && XS.term) { XS.stack.push({ html: CURHTML, y: await getY() }); await load(th, false); } else { await loadX(th); XS.term = true; } }
        else if (path === "about") await loadX(aboutHTML(aboutChart(), CHK_RES, { a: q.a }));
        else if (path === "chk") { (q.k === "all" ? CHK.map(c => c[0]) : [q.k]).forEach(k => { const c = CHK.find(x => x[0] === k); if (c) CHK_RES[k] = c[3](); });
          await loadX(aboutHTML(aboutChart(), CHK_RES, { open: q.k })); }
      } catch (e) { await show("เกิดข้อผิดพลาด", String((e && e.message) || e)); }
    })();
    return false;
  };
  await showChart();
  await wv.present(true);
}

